def __repr__(self):
    cn = self.__class__.__name__
    parts = [repr(self.spec)]
    if self.types:
        type_names = tuple(t.__name__ for t in self.types)
        if len(type_names) == 1:
            parts.append('type=%r' % (type_names[0],))
        else:
            parts.append('type=%r' % (type_names,))
    if self.instance_of:
        inst_names = tuple(t.__name__ for t in self.instance_of)
        if len(inst_names) == 1:
            parts.append('instance_of=%r' % (inst_names[0],))
        else:
            parts.append('instance_of=%r' % (inst_names,))
    if self.vals:
        parts.append('vals=%r' % self.vals)
    if self.validators:
        val_names = [getattr(v, '__name__', '#%d' % i) for i, v in enumerate(self.validators)]
        parts.append('validate=%r' % val_names)
    return '%s(%s)' % (cn, ', '.join(parts))

